mapper.select:
select transaction_id, user_id, category_id, payment_method_id, period_id, transaction_date, transaction_amount, transaction_type, transaction_title, create_at, memo
from TBL_TRANSACTION
where USER_ID = #{userId} and PERIOD_ID = #{periodId}

select coalesce(sum(TBL_TRANSACTION.TRANSACTION_AMOUNT), 0) as totalAmount
from TBL_TRANSACTION
where USER_ID = #{userId}
  and PERIOD_ID = #{periodId}
  and TRANSACTION_TYPE = #{transactionType}
